  displaySource: [
    "// Command",
    "//",
    "// Each request becomes an object with execute() and undo(). The editor does",
    "// not run edits directly: it runs commands and keeps them on a history stack,",
    "// so undoing is just popping the last one and asking it to reverse itself.",
    "#include <string>",
    "#include <vector>",
    "",
    "",
    "// The receiver: the object the commands act on.",
    "struct Document {",
    "    std::string text;",
    "};",
    "",
    "// The command interface.",
    "struct Command {",
    "    virtual void execute() = 0;",
    "    virtual void undo() = 0;",
    "    virtual std::string id() const = 0;",
    "    virtual ~Command() = default;",
    "};",
    "",
    "class Insert : public Command {",
    "    Document& doc;",
    "    std::string what;",
    "    std::string name;",
    "",
    "  public:",
    "    Insert(Document& d, std::string w, std::string n) : doc(d), what(w), name(n) {}",
    "    void execute() override {",
    "        doc.text += what;",
    "    }",
    "    void undo() override {",
    "        doc.text.erase(doc.text.size() - what.size());",
    "    }",
    "    std::string id() const override { return name; }",
    "};",
    "",
    "class Editor {",
    "    Document& doc;",
    "    std::vector<Command*> history;",
    "",
    "  public:",
    "    explicit Editor(Document& d) : doc(d) {}",
    "",
    "    void run(Command* c) {",
    "        c->execute();",
    "        history.push_back(c);",
    "        say(\"typed  -> \\\"%s\\\"\", doc.text.c_str());",
    "    }",
    "",
    "    void undo() {",
    "        if (history.empty()) {",
    "            say(\"nothing to undo\");",
    "            return;",
    "        }",
    "        Command* c = history.back();",
    "        history.pop_back();",
    "        c->undo();",
    "        say(\"undo   -> \\\"%s\\\"\", doc.text.c_str());",
    "    }",
    "};",
    "",
    "",
    "int main() {",
    "    {",
    "        Document doc;",
    "        Editor editor(doc);",
    "        Insert c1(doc, \"Hello\", \"c1\"), c2(doc, \", world\", \"c2\"), c3(doc, \"!\", \"c3\");",
    "        editor.run(&c1);",
    "        editor.run(&c2);",
    "        editor.run(&c3);",
    "        editor.undo();",
    "    }",
    "",
    "    {",
    "        Document doc;",
    "        Editor editor(doc);",
    "        Insert c1(doc, \"Hello\", \"c1\"), c2(doc, \", world\", \"c2\"), c3(doc, \"!\", \"c3\");",
    "        editor.run(&c1);",
    "        editor.run(&c2);",
    "        editor.undo();",
    "        editor.undo();",
    "        editor.undo();",
    "    }",
    "",
    "    return 0;",
    "}"
  ],
